"""Source-bound cyclist right-edge and standing-vehicle geometry measurement.

Geometry is evidence for review, never a definition of practicability or due care.
"""
import hashlib
import json
import math
from pathlib import Path

FRAMES = 600
VIEWS = {'overview', 'approach', 'reference_corner', 'driver_reference'}
SOURCES = ('native-cycle-frames.jsonl', 'native-map-readback.json',
           'standing-vehicle.json', 'video_frames.jsonl')


def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _number(value):
    return type(value) in (int, float) and math.isfinite(value)


def _rectangle(value, name):
    if not isinstance(value, list) or len(value) != 4 or not all(
            isinstance(point, list) and len(point) == 2 and all(_number(v) for v in point)
            for point in value):
        raise ValueError('Invalid ' + name + ' footprint')
    xs = [point[0] for point in value]
    ys = [point[1] for point in value]
    if max(xs) - min(xs) < .05 or max(ys) - min(ys) < .05:
        raise ValueError('Degenerate ' + name + ' footprint')
    return min(xs), max(xs), min(ys), max(ys)


def measure(folder, expected_hashes, diagnostic=False):
    folder = Path(folder)
    if set(expected_hashes) != set(SOURCES):
        raise ValueError('Complete saved-source hash inventory required')
    for name in SOURCES:
        if digest(folder / name) != expected_hashes[name]:
            raise ValueError('Saved source changed: ' + name)
    road = json.loads((folder / SOURCES[1]).read_text())
    standing = json.loads((folder / SOURCES[2]).read_text())
    if road.get('format') != 'c230259-road-edge-v1' or road.get('right_edge_source') not in (
            ('synthetic_cpu',) if diagnostic else ('native_map_readback',)):
        raise ValueError('Roadway right-edge source differs')
    if standing.get('format') != 'c230259-standing-vehicle-v1' or standing.get('source_kind') not in (
            ('synthetic_cpu',) if diagnostic else ('native_actor',)):
        raise ValueError('Standing-vehicle source differs')
    edge = road.get('right_roadway_edge_y_m')
    if not _number(edge) or road.get('right_side') != 'lower_y':
        raise ValueError('Calibrated right roadway edge absent')
    sx0, sx1, sy0, sy1 = _rectangle(standing.get('body_native_xy_m'), 'standing vehicle')
    if sy1 >= edge:
        raise ValueError('Standing vehicle is not outside right roadway edge')
    tracks = [json.loads(line) for line in (folder / SOURCES[0]).read_text().splitlines()]
    frames = [json.loads(line) for line in (folder / SOURCES[3]).read_text().splitlines()]
    if len(tracks) != FRAMES or len(frames) != FRAMES:
        raise ValueError('Complete 30-second frame window required')
    actor_id = None
    pass_frames = []
    margins = []
    clearances = []
    first_time = None
    for i, (track, frame) in enumerate(zip(tracks, frames)):
        if first_time is None:
            first_time = track.get('time_s')
            if not _number(first_time):
                raise ValueError('Initial Native time absent')
        if (track.get('frame') != i or frame.get('video_frame') != i or
                track.get('native_frame') != frame.get('native_frame') or
                frame.get('carla_frame') != frame.get('native_frame') or
                not _number(track.get('time_s')) or not _number(frame.get('time_s')) or
                abs(track['time_s'] - (first_time + i / 20)) > .0025 or
                abs(frame['time_s'] - track['time_s']) > .0025):
            raise ValueError('Cycle and four-camera frame join differs')
        if track.get('source_kind') not in (
                ('synthetic_native_sample',) if diagnostic else ('native_actor',)):
            raise ValueError('Cycle provenance differs')
        if actor_id is None:
            actor_id = track.get('actor_id')
        if not isinstance(actor_id, int) or track.get('actor_id') != actor_id:
            raise ValueError('Cycle actor identity differs')
        if track.get('blueprint') not in ('vehicle.bh.crossbike', 'vehicle.diamondback.century',
                                          'vehicle.gazelle.omafiets'):
            raise ValueError('Cycle identity or blueprint unsupported')
        hashes = frame.get('source_rgb_sha256')
        if not isinstance(hashes, dict) or set(hashes) != VIEWS or any(
                not isinstance(v, str) or len(v) != 64 for v in hashes.values()):
            raise ValueError('Four source-camera hashes absent')
        x0, x1, y0, y1 = _rectangle(track.get('body_native_xy_m'), 'cycle')
        if y0 < edge:
            raise ValueError('Cycle footprint crossed calibrated roadway edge')
        margins.append(y0 - edge)
        if x1 >= sx0 and x0 <= sx1:
            pass_frames.append(i)
            clearances.append(y0 - sy1)
    if not pass_frames:
        raise ValueError('Standing-vehicle passing interval absent')
    return {'format': 'c230259-right-edge-measurement-v1',
            'frames': FRAMES, 'rate_hz': 20,
            'right_edge_body_margin_min_m': round(min(margins), 5),
            'right_edge_body_margin_median_m': round(sorted(margins)[len(margins)//2], 5),
            'standing_vehicle_pass_frames': pass_frames,
            'standing_vehicle_clearance_min_m': round(min(clearances), 5),
            'source_hashes': expected_hashes,
            'source_kind': 'synthetic_diagnostic' if diagnostic else 'original_native',
            'practicability_reviewed': False, 'due_care_reviewed': False,
            'exception_status': 'unreviewed', 'legal_verdict': None}

"""Saved-only bicycle right-edge measurements; qualitative law review stays open."""
import argparse
import hashlib
import json
from pathlib import Path

from measure_right_edge import SOURCES, digest, measure

CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')


def required(root, name):
    path = root / name
    if not path.is_file():
        raise ValueError('Missing required source: ' + name)
    return path


def rows(path):
    return [json.loads(line) for line in path.read_text().splitlines()]


def measure_activation(scope, context):
    return {'bicycle_source': scope['source_kind'], 'roadway_readback': True,
            'standing_vehicle_present': True, 'classification_review_pending': True}


def measure_speed_exception(scope, context):
    return {'nearby_moving_traffic_count': context['nearby_moving_traffic_count'],
            'lawful_commensurate_speed_review_pending': True}


def measure_left_turn_exception(scope, context):
    return {'left_turn_requested': context['left_turn_requested'],
            'preparation_review_pending': True}


def measure_position_and_care(scope, context):
    return {'right_edge_body_margin_min_m': scope['right_edge_body_margin_min_m'],
            'standing_vehicle_clearance_min_m': scope['standing_vehicle_clearance_min_m'],
            'practicability_reviewed': False, 'due_care_reviewed': False}


def measure_unsafe_context(scope, context):
    return {'standing_vehicle_pass_frames': len(scope['standing_vehicle_pass_frames']),
            'unsafe_to_keep_right_review_pending': True}


def measure_object_hazard(scope, context):
    return {'standing_vehicle_recorded': True, 'other_hazard_inventory': context['other_hazard_inventory'],
            'impeded_right_access_review_pending': True}


def measure_narrow_lane(scope, context):
    return {'driving_lane_width_m': context['driving_lane_width_m'],
            'side_by_side_safety_review_pending': True}


def measure_selected_witness(scope, context):
    return {'passing_frames': len(scope['standing_vehicle_pass_frames']),
            'right_edge_margin_m': scope['right_edge_body_margin_min_m'],
            'passing_clearance_m': scope['standing_vehicle_clearance_min_m']}


MEASUREMENTS = (
    ('activation', measure_activation, ('native-cycle-frames.jsonl', 'native-map-readback.json', 'standing-vehicle.json', 'context.json')),
    ('speed_exception', measure_speed_exception, ('native-cycle-frames.jsonl', 'context.json')),
    ('left_turn_exception', measure_left_turn_exception, ('native-cycle-frames.jsonl', 'context.json')),
    ('position_and_care', measure_position_and_care, ('native-cycle-frames.jsonl', 'native-map-readback.json', 'standing-vehicle.json')),
    ('unsafe_context', measure_unsafe_context, ('native-cycle-frames.jsonl', 'standing-vehicle.json', 'context.json')),
    ('object_hazard', measure_object_hazard, ('standing-vehicle.json', 'context.json')),
    ('narrow_lane', measure_narrow_lane, ('native-map-readback.json', 'context.json')),
    ('selected_witness', measure_selected_witness, ('native-cycle-frames.jsonl', 'standing-vehicle.json')),
)


def finalize(attempt, output):
    root = Path(attempt)
    config = json.loads(required(root, 'config.json').read_text())
    for name in (*SOURCES, 'context.json', 'trace.jsonl', 'capture/evidence.jsonl'):
        required(root, name)
    for name in CAMERAS:
        required(root, name + '.mkv')
    expected = {name: digest(root / name) for name in SOURCES}
    context = json.loads((root / 'context.json').read_text())
    if context.get('law_id') != config['law_id'] or context.get('legal_verdict') is not None:
        raise ValueError('Wrong law or asserted legal verdict in saved context')
    diagnostic = context.get('source_kind') == 'synthetic_cpu'
    scope = measure(root, expected, diagnostic=diagnostic)
    tracks, mapping, trace, capture = (rows(root / name) for name in
        ('native-cycle-frames.jsonl', 'video_frames.jsonl', 'trace.jsonl', 'capture/evidence.jsonl'))
    if any(len(stream) != 600 for stream in (tracks, mapping, trace, capture)):
        raise ValueError('Full 600-frame saved source required')
    for track, frame, state, event in zip(tracks, mapping, trace, capture):
        original = track['native_frame']
        if (frame['native_frame'] != original or state['frame'] != original or
                event['original_frame'] != original or
                any(frame['camera_native_frames'][name] != original for name in CAMERAS)):
            raise ValueError('Saved bicycle, trace and camera frame join differs')
    measurements = {key: {'method': function.__name__, 'value': function(scope, context),
                          'sources': {name: digest(root / name) for name in sources}}
                    for key, function, sources in MEASUREMENTS}
    channel_dir = root / 'channels'
    channel_dir.mkdir(exist_ok=True)
    recording = []
    for item in config['recording_description']['channels']:
        name = item['name']
        path = channel_dir / (name.replace('/', '_') + '.jsonl')
        path.write_text(''.join(json.dumps({'time_s': row['time_s'], 'value': {
            'actor_id': row['actor_id'], 'body_native_xy_m': row['body_native_xy_m'],
            'standing_body_native_xy_m': row['standing_body_native_xy_m'],
            'source_kind': row['source_kind']}}, separators=(',', ':')) + '\n' for row in tracks))
        recording.append({'name': name, 'unit': item['unit'], 'reference': 'channels/' + path.name})
    for item in config['recording_description']['context_inputs']:
        name = item['name']
        path = channel_dir / (name.replace('/', '_') + '.json')
        path.write_text(json.dumps({name: context}, separators=(',', ':')) + '\n')
        recording.append({'name': name, 'unit': item['unit'], 'reference': 'channels/' + path.name})
    result = {'case_id': config['case_id'], 'measured_values': {key: value for key, value in scope.items() if key != 'legal_verdict'},
              'target_checks': [{'target': 'requested_cycle_center_y_m',
                'requested': config['requested_cycle_center_y_m'],
                'measured': round(sum(point[1] for point in tracks[300]['body_native_xy_m']) / 4, 5),
                'method': 'saved original bicycle body centroid', 'tolerance': .4,
                'matched': abs(sum(point[1] for point in tracks[300]['body_native_xy_m']) / 4 - config['requested_cycle_center_y_m']) <= .4,
                'physical_cause_confirmed': False, 'cause_evidence': ['native-cycle-frames.jsonl']}],
              'setup_confirmed': not diagnostic, 'behavior_attempted': not diagnostic,
              'maneuver_completed': not diagnostic,
              'termination_reason': 'full original source window' if not diagnostic else 'synthetic diagnostic window',
              'physical_failure_flags': ['physical_bicycle_and_due_care_review_pending'],
              'trace_reference': 'trace.jsonl',
              'video_references': [name + '.mkv' for name in CAMERAS],
              'video_frame_map_reference': 'video_frames.jsonl',
              'recording_description': config['recording_description'],
              'recording_evidence': recording,
              'realized_observables': {'right_edge_body_margin_min_m': {'value': scope['right_edge_body_margin_min_m'],
                  'unit': 'm', 'method': 'saved body/roadway edge join', 'time_window': '600 frames',
                  'statistic': 'minimum', 'reference': 'native-cycle-frames.jsonl'}},
              'provenance_kind': 'synthetic_cpu' if diagnostic else 'native',
              'accepted': False, 'legal_verdict_claimed': False}
    from worker_exchange.native_output import validate_result
    validate_result(result)
    if (root / 'result.json').exists():
        raise ValueError('Saved processing cannot overwrite a prior result')
    (root / 'result.json').write_text(json.dumps(result, indent=2) + '\n')
    report = {'format': 'c230259-right-edge-saved-analysis-v1', 'case_id': config['case_id'],
              'measurements': measurements, 'right_edge_scope': scope,
              'original_native_source': not diagnostic, 'legal_verdict': None}
    Path(output).write_text(json.dumps(report, indent=2) + '\n')
    return report


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--attempt', required=True)
    parser.add_argument('--output', required=True)
    args = parser.parse_args()
    print(json.dumps(finalize(args.attempt, args.output)))


if __name__ == '__main__':
    main()

"""Exact draft saved-source tests; synthetic input cannot be original evidence."""
import sys
from pathlib import Path
import tempfile
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from prove_right_edge import sample, hashes
from runner import check, process_saved


class SavedSourceTest(unittest.TestCase):
    def test_exact_config(self):
        self.assertTrue(check()['saved_source_path_checked'])

    def test_synthetic_rejected_as_original(self):
        with tempfile.TemporaryDirectory(dir=Path(__import__('os').environ['TMPDIR']).resolve()) as tmp:
            folder = Path(tmp) / 'reference'
            sample(folder, 'reference')
            with self.assertRaisesRegex(ValueError, 'source differs'):
                process_saved(folder, hashes(folder))


if __name__ == '__main__':
    unittest.main()

class NativeMapSurveyTest(unittest.TestCase):
    def test_original_map_readback(self):
        from capture import _survey
        from geometry import open_drive
        class Location:
            def __init__(self, x, y, z):
                self.x, self.y, self.z = x, y, z
        class Carla:
            class LaneType:
                Driving = 'driving'
        Carla.Location = Location
        class Map:
            def to_opendrive(self):
                return open_drive()
            def get_waypoint(self, location, project_to_road, lane_type):
                if not project_to_road or lane_type != 'driving':
                    raise AssertionError('Wrong Native lane query')
                class Waypoint:
                    road_id = 1
                    lane_id = -1
                    transform = type('T', (), {'location': type('P', (), {'y': -1.75})()})()
                return Waypoint()
        row = _survey(Map(), Carla)
        self.assertEqual(row['right_roadway_edge_y_m'], -3.5)
        self.assertEqual(len(row['native_waypoint_samples']), 4)

    def test_changed_native_width_rejected(self):
        from capture import _survey
        from geometry import open_drive
        class Map:
            def to_opendrive(self):
                return open_drive().replace('a="3.5"', 'a="4.0"', 1)
        with self.assertRaisesRegex(RuntimeError, 'width readback'):
            _survey(Map(), object())
